package me.pikanote.companion;
import android.content.Context;import android.graphics.*;import android.view.*;import java.util.function.Consumer;
/** Independent Android surface; page scrolling and transforms cannot move it. */
final class NativeNavigation extends View {
 final String[] tabs={"today","memories","tasks","events","ask","setup"};final String[] names={"Today","Memories","Tasks","Events","Ask","Config"};final Consumer<String> navigate;final Paint p=new Paint(3);int selected=0;boolean dark;
 NativeNavigation(Context c,Consumer<String> action){super(c);navigate=action;setLayerType(View.LAYER_TYPE_HARDWARE,null);setContentDescription("Main navigation");setFocusable(true);setElevation(5*c.getResources().getDisplayMetrics().density);}
 void select(String tab){for(int i=0;i<tabs.length;i++)if(tabs[i].equals(tab)||i==5&&(tab.equals("calendar")||tab.equals("archive")||tab.equals("help")))selected=i;invalidate();}
 void theme(boolean value){dark=value;invalidate();}
 void line(Canvas c,float... xy){Path path=new Path();path.moveTo(xy[0],xy[1]);for(int i=2;i<xy.length;i+=2)path.lineTo(xy[i],xy[i+1]);c.drawPath(path,p);}
 @Override protected void onDraw(Canvas c){super.onDraw(c);float d=getResources().getDisplayMetrics().density;p.setStyle(Paint.Style.FILL);p.setColor(dark?0xff33352f:0xffe8e6df);c.drawRoundRect(0,0,getWidth(),getHeight(),28*d,28*d,p);float cell=getWidth()/6f;for(int i=0;i<6;i++){float x=cell*(i+.5f),y=getHeight()/2f;if(i==selected){p.setColor(0xfffa5438);c.drawRoundRect(x-25*d,y-25*d,x+25*d,y+25*d,18*d,18*d,p);}c.save();c.translate(x-12*d,y-12*d);c.scale(d,d);p.setStyle(Paint.Style.STROKE);p.setStrokeWidth(1.8f);p.setStrokeCap(Paint.Cap.ROUND);p.setStrokeJoin(Paint.Join.ROUND);p.setColor(i==selected?Color.WHITE:dark?0xffc7c1b5:0xff5f5d57);switch(i){case 0:line(c,3,11,12,3,21,11);line(c,5,10,5,21,19,21,19,10);line(c,9,21,9,14,15,14,15,21);break;case 1:c.drawRoundRect(5,3,19,21,2,2,p);line(c,8,8,16,8);line(c,8,12,16,12);line(c,8,16,13,16);break;case 2:c.drawCircle(5,6,2,p);c.drawCircle(5,12,2,p);c.drawCircle(5,18,2,p);line(c,11,6,21,6);line(c,11,12,21,12);line(c,11,18,21,18);break;case 3:c.drawRoundRect(3,5,21,21,2,2,p);line(c,3,10,21,10);line(c,7,3,7,7);line(c,17,3,17,7);line(c,8,15,11,18,17,12);break;case 4:c.drawRoundRect(3,3,21,18,4,4,p);line(c,7,18,5,22,13,18);line(c,8,8,16,8);line(c,8,12,14,12);break;case 5:line(c,3,6,21,6);line(c,3,12,21,12);line(c,3,18,21,18);c.drawCircle(8,6,2,p);c.drawCircle(16,12,2,p);c.drawCircle(10,18,2,p);break;}c.restore();p.setStyle(Paint.Style.FILL);}}
 @Override public boolean onTouchEvent(MotionEvent e){if(e.getAction()==MotionEvent.ACTION_DOWN)return true;if(e.getAction()==MotionEvent.ACTION_UP){int n=Math.max(0,Math.min(5,(int)(e.getX()/(getWidth()/6f))));performClick();navigate.accept(tabs[n]);return true;}return true;}
 @Override public boolean performClick(){super.performClick();return true;}
}
